58	    pub async fn check_all(&self) -> Result<Vec<IdentityStatus>, MonitorError> {
59	        let store = IdentityStore;
60	        let dids = store
61	            .list_identities()
62	            .map_err(|e| MonitorError::IdentityStoreError {
63	                message: e.to_string(),
64	            })?;
65	
66	        let mut statuses = Vec::new();
67	        for did in &dids {
68	            match self.check_for_changes(did).await {
69	                Ok(unauthorized) => {
70	                    statuses.push(IdentityStatus {
71	                        did: did.clone(),
72	                        check_failed: false,
73	                        unauthorized_changes: unauthorized,
74	                    });
75	                }
76	                Err(e) => {
77	                    tracing::warn!(did = did.as_str(), error = %e, "check failed for identity, continuing with remaining");
78	                    statuses.push(IdentityStatus {
79	                        did: did.clone(),
80	                        check_failed: true,
81	                        unauthorized_changes: vec![],
82	                    });
83	                }
84	            }
85	        }
86	        Ok(statuses)
87	    }
