219	const MONITOR_INTERVAL_SECS: u64 = 15 * 60; // 15 minutes
220	
221	/// Run a single monitoring cycle. Extracted from the loop for testability.
222	/// Returns the list of identity statuses with any alerts.
223	pub async fn run_monitoring_cycle(monitor: &PlcMonitor<'_>) -> Vec<IdentityStatus> {
224	    match monitor.check_all().await {
225	        Ok(statuses) => statuses,
226	        Err(e) => {
227	            tracing::warn!(error = %e, "Monitoring cycle check_all failed");
228	            vec![]
229	        }
230	    }
231	}
