233	/// Run the PLC monitoring loop. Spawned once during app setup.
234	/// Checks all managed identities every MONITOR_INTERVAL_SECS and emits
235	/// "plc_alert" events to the frontend when unauthorized changes are detected.
236	pub async fn run_monitoring_loop(app_handle: tauri::AppHandle) {
237	    let mut interval = interval(Duration::from_secs(MONITOR_INTERVAL_SECS));
238	    // Don't burst-fire missed ticks after iOS suspension
239	    interval.set_missed_tick_behavior(MissedTickBehavior::Delay);
240	    // Skip the first immediate tick — let the app finish initializing
241	    interval.tick().await;
242	
243	    loop {
244	        interval.tick().await;
245	
246	        let state = app_handle.state::<crate::oauth::AppState>();
247	        let monitor = PlcMonitor::new(state.pds_client());
248	        let statuses = run_monitoring_cycle(&monitor).await;
249	
250	        emit_if_alerts(&app_handle, &statuses);
251	    }
252	    // If the loop ever exits (shouldn't happen), log it so we know monitoring died.
253	    // The `loop` above has no `break`, so control never falls through here — the
254	    // allow keeps this defensive epilogue compiling as intentional dead code.
255	    #[allow(unreachable_code)]
256	    {
257	        tracing::error!("PLC monitoring loop exited unexpectedly");
258	    }
259	}
