271	/// Tauri IPC command: check all managed identities for unauthorized PLC operations.
272	/// Also emits "plc_alert" event so IdentityListHome's event listener receives updates.
273	#[tauri::command]
274	pub async fn check_identity_status(
275	    app: tauri::AppHandle,
276	    state: tauri::State<'_, crate::oauth::AppState>,
277	) -> Result<Vec<IdentityStatus>, MonitorError> {
278	    let monitor = PlcMonitor::new(state.pds_client());
279	    let statuses = monitor.check_all().await?;
280	    emit_if_alerts(&app, &statuses);
281	    Ok(statuses)
282	}
