482	    /// The wallet's own re-key op — a device-key-signed rotation that inserts a recovery key at
483	    /// rotationKeys[1] (device stays [0], the PDS key shifts to [2]) — must be treated as an
484	    /// AUTHORIZED change and raise no tamper alert. Authorization is by signature
485	    /// (the device key signed it), independent of what the op does to the key set.
486	    #[tokio::test]
487	    async fn rekey_op_signed_by_device_key_is_authorized() {
488	        use httpmock::prelude::*;
489	        use p256::ecdsa::{signature::Signer, SigningKey};
490	        use p256::FieldBytes;
491	        use std::collections::BTreeMap;
492	
493	        let did = "did:plc:rekeyauthorized";
494	        let (device_pub, device_priv) = setup_identity(did);
495	        let device_uri = DidKeyUri(device_pub.key_id.clone());
496	
497	        // The PDS repo key and the fresh recovery key (in reality HKDF-derived; any did:key
498	        // stands in for the monitor, which only checks the op's signature).
499	        let pds_kp = crypto::generate_p256_keypair().expect("pds keygen");
500	        let recovery_kp = crypto::generate_p256_keypair().expect("recovery keygen");
501	
502	        // A device-key sign closure (low-S) — the same shape `per_did_sign_closure` produces.
503	        // `device_priv` is `[u8; 32]` (Copy), so both closures below capture their own copy.
504	        let device_sign = move |data: &[u8]| {
505	            let field_bytes: FieldBytes = device_priv.into();
506	            let sk = SigningKey::from_bytes(&field_bytes).expect("valid device key");
507	            let sig: p256::ecdsa::Signature = Signer::sign(&sk, data);
508	            let sig = sig.normalize_s().unwrap_or(sig);
509	            Ok::<_, crypto::CryptoError>(sig.to_bytes().to_vec())
510	        };
511	
512	        // Old-model genesis: rotationKeys = [device, PDS], signed by the device key.
513	        let genesis = crypto::build_did_plc_genesis_op_with_external_signer(
514	            &device_uri,
515	            &pds_kp.key_id,
516	            "alice.test",
517	            "https://pds.test",
518	            device_sign,
519	        )
520	        .expect("genesis op");
521	        let genesis_op: serde_json::Value =
522	            serde_json::from_str(&genesis.signed_op_json).expect("parse genesis");
523	
524	        // The re-key: additively insert the recovery key at [1], device stays [0], PDS → [2].
525	        let mut vms = BTreeMap::new();
526	        vms.insert("atproto".to_string(), pds_kp.key_id.0.clone());
527	        let mut services = BTreeMap::new();
528	        services.insert(
529	            "atproto_pds".to_string(),
530	            crypto::PlcService {
531	                service_type: "AtprotoPersonalDataServer".to_string(),
532	                endpoint: "https://pds.test".to_string(),
533	            },
534	        );
535	        let rekey = crypto::build_did_plc_rotation_op(
536	            "bafy_rekey_genesis",
537	            vec![
538	                device_pub.key_id.clone(),
539	                recovery_kp.key_id.0.clone(),
540	                pds_kp.key_id.0.clone(),
541	            ],
542	            vms,
543	            vec!["at://alice.test".to_string()],
544	            services,
545	            device_sign,
546	        )
547	        .expect("re-key rotation op");
548	        let rekey_op: serde_json::Value =
549	            serde_json::from_str(&rekey.signed_op_json).expect("parse re-key");
550	
551	        let audit_log = serde_json::json!([
552	            {
553	                "did": did,
554	                "cid": "bafy_rekey_genesis",
555	                "createdAt": "2026-03-29T00:00:00Z",
556	                "nullified": false,
557	                "operation": genesis_op
558	            },
559	            {
560	                "did": did,
561	                "cid": "bafy_rekey_rotation",
562	                "createdAt": "2026-03-29T01:00:00Z",
563	                "nullified": false,
564	                "operation": rekey_op
565	            }
566	        ]);
567	
568	        let mock_server = MockServer::start();
569	        let client = PdsClient::new_for_test(mock_server.base_url());
570	        let monitor = PlcMonitor::new(&client);
571	        mock_server.mock(|when, then| {
572	            when.method(GET).path(format!("/{did}/log/audit"));
573	            then.status(200)
574	                .header("content-type", "application/json")
