1	import { getDeadline, getUrgency, type Urgency } from './deadline';
2	import { isDidWeb } from './did-doc-utils';
3	import type { UnauthorizedChange } from './ipc';
4	
5	/**
6	 * The identity screen's status panel state — the large-format sibling of `UrgencyBadge`,
7	 * sharing its four-state vocabulary so one identity reads the same at both sizes.
8	 *
9	 * The panel's `safe` and the badge's `safe` mean different things on purpose. The badge
10	 * only ever renders *inside* an alarm, where `safe` means "more than 24h of recovery
11	 * window left" — never "all clear". The panel is the identity's whole answer to "am I
12	 * okay?", so its `safe` is the all-clear and an active unauthorized change can never
13	 * produce it, however much window remains. That is why this derivation exists instead
14	 * of calling `getUrgency()` on an alert deadline directly.
15	 */
16	export type IdentityPanelState = {
17	  urgency: Urgency;
18	  /**
19	   * The recovery deadline the panel counts down to: the soonest still-open window while
20	   * the alarm is live, the last one to close once they all have. `null` outside the alarm
21	   * states, and also when an alarm's timestamps were unreadable (see below).
22	   */
23	  deadline: Date | null;
24	  /** Unauthorized changes behind the alarm; 0 in every non-alarm state. */
25	  alertCount: number;
26	};
27	
28	/**
29	 * Fold what the wallet knows about one identity into a single panel state.
30	 *
31	 * Precedence — an unauthorized change outranks a dead device key, the inverse of the home
32	 * list's card strips. The strips order by *what the user should do next*, where recovery
33	 * has to come first because the override needs the key that is missing. The panel reports
34	 * *what is true*, and "someone is rewriting your identity right now" is the more severe
35	 * fact regardless of which remedy runs first. The warning state's copy is what routes the
36	 * user to recovery; it does not need to outrank the alarm to do that.
37	 */
38	export function deriveIdentityPanelState(
39	  changes: UnauthorizedChange[],
40	  deviceKeyUnusable: boolean,
41	  now: number = Date.now()
42	): IdentityPanelState {
43	  if (changes.length > 0) {
44	    const deadlines: Date[] = [];
45	    for (const change of changes) {
46	      try {
47	        deadlines.push(getDeadline(change.createdAt));
48	      } catch {
49	        // An unreadable timestamp costs us the countdown, never the alarm: the change is
50	        // still an unauthorized rewrite of this identity. Falling through to `safe` here
51	        // would hide an attack behind a parsing bug, so the alarm is raised without one.
52	      }
53	    }
54	
55	    const open = deadlines.filter((d) => getUrgency(d, now) !== 'expired');
56	    if (open.length > 0) {
57	      return {
58	        urgency: 'critical',
59	        deadline: open.reduce((a, b) => (a.getTime() <= b.getTime() ? a : b)),
60	        alertCount: changes.length,
61	      };
62	    }
63	
64	    // Every window has closed. Ashen, not alarm — the distinction the design brief draws
65	    // between "act now" and "the moment to act has passed".
66	    return {
67	      urgency: 'expired',
68	      deadline:
69	        deadlines.length > 0
70	          ? deadlines.reduce((a, b) => (a.getTime() >= b.getTime() ? a : b))
71	          : null,
72	      alertCount: changes.length,
73	    };
74	  }
75	
76	  if (deviceKeyUnusable) {
77	    return { urgency: 'warning', deadline: null, alertCount: 0 };
78	  }
79	
80	  return { urgency: 'safe', deadline: null, alertCount: 0 };
81	}
82	
83	/**
84	 * Whether a panel state for `did` rests on a reading the wallet could actually take.
85	 *
86	 * `plcCheckSucceeded` is `!IdentityStatus.checkFailed` — the monitor's report of whether
87	 * plc.directory answered. It is the right input for a did:plc and a meaningless one for a
88	 * did:web, which has no PLC audit log at all: `PlcMonitor::check_all` does not filter by
89	 * DID method, so it asks plc.directory about every managed DID and a did:web's audit-log
90	 * fetch fails there *every* sweep. Passing that through would tell a did:web user their
91	 * public record could not be reached when they have no public record — the exact opposite
92	 * of the honesty the unverified state exists to provide.
93	 *
94	 * So a did:web is verified by construction. Its protection is control of its domain, which
95	 * no directory sweep observes in either direction.
96	 */
97	export function isVerified(did: string, plcCheckSucceeded: boolean): boolean {
98	  return isDidWeb(did) || plcCheckSucceeded;
99	}
100	
101	/**
102	 * The one label vocabulary the badge and the panel share, so an identity reads the same
103	 * whichever size it is rendered at.
104	 *
105	 * `verified` is a qualifier on the *evidence*, not a fifth state: when the directory could
106	 * not be reached (`IdentityStatus.checkFailed`), the wallet has no fresh reading, and a
107	 * panel saying "Secure" would be asserting something it did not check. The identity is not
108	 * in danger — only our knowledge of it is stale — so it stays in the `safe` state and says
109	 * so plainly instead.
110	 */
111	export function panelLabel(urgency: Urgency, verified: boolean = true): string {
112	  switch (urgency) {
113	    case 'safe':
114	      return verified ? 'Secure' : 'Not checked';
115	    case 'warning':
116	      return 'Action needed';
117	    case 'critical':
118	      return 'Under attack';
119	    case 'expired':
120	      return 'Recovery window closed';
121	  }
122	}
123	
124	/**
125	 * "Directory checked N ago" for the secure panel.
126	 *
127	 * The wallet has no stored sweep timestamp to read (exposing the background monitor's
128	 * history is its own piece of work), so the only honest source is the check this screen
129	 * ran itself. Sub-minute reads as "just now" rather than "0 minutes ago", and anything
130	 * past a day stops counting — a figure that stale is better stated vaguely than precisely.
131	 */
132	export function formatCheckedAgo(checkedAt: number, now: number = Date.now()): string {
133	  const elapsed = now - checkedAt;
134	  if (elapsed < 60_000) return 'just now';
135	  const minutes = Math.floor(elapsed / 60_000);
136	  if (minutes < 60) return `${minutes} min ago`;
137	  const hours = Math.floor(minutes / 60);
138	  if (hours < 24) return `${hours}h ago`;
139	  return 'over a day ago';
140	}
